abstract class StorageEngine {
  constructor(protected readonly namespace: string) {}
  abstract load<T>(key: string): T | null;
  protected scoped(key: string): string { return `${this.namespace}:${key}`; }
}
class MemoryEngine extends StorageEngine {
  private map = new Map<string, unknown>();
  override load<T>(key: string): T | null { return (this.map.get(this.scoped(key)) as T) ?? null; }
}

