interface QuizSubmission { sectionId: string; score: number }
function parseSubmission(raw: unknown): QuizSubmission {
  if (typeof raw !== 'object' || raw === null) throw new TypeError('Expected object');
  const obj = raw as Record<string, unknown>;
  if (typeof obj.sectionId !== 'string' || typeof obj.score !== 'number') {
    throw new TypeError('Invalid submission fields');
  }
  return { sectionId: obj.sectionId, score: obj.score };
}
console.log(parseSubmission({ sectionId: 'ts-s1', score: 90 }));

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };
type ParseError = 'EMPTY' | 'NOT_A_NUMBER';

function parseScore(input: string): Result<number, ParseError> {
  if (!input.trim()) return { ok: false, error: 'EMPTY' };
  const n = Number(input);
  return Number.isFinite(n) ? { ok: true, value: n } : { ok: false, error: 'NOT_A_NUMBER' };
}
const r = parseScore('88');
console.log(r.ok ? r.value : r.error);

